import Foundation
import Testing
@testable import OpenDollarsCore

// Port of web/src/i18n/copy-rules.test.ts over what the iOS app ships: Localizable.xcstrings and
// InfoPlist.xcstrings, generated by ios/scripts/sync-strings.mjs from the web's locale files and
// ios/strings/ios-only.json. The web test covers the web copy; this one also covers the texts only
// the iOS app has, and checks the conversion kept every placeholder.

/// One text of a string catalog, in one language (a plural variation is one text).
struct CatalogText: Sendable, CustomStringConvertible {
    let catalog: String
    let key: String
    let language: String
    let text: String

    var description: String { "\(catalog) \(language) \(key): \(text)" }
}

enum StringCatalogs {
    static let resources = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent() // OpenDollarsCoreTests
        .deletingLastPathComponent() // Tests
        .deletingLastPathComponent() // OpenDollarsCore
        .deletingLastPathComponent() // ios
        .appendingPathComponent("OpenDollars/Resources")

    static let names = ["Localizable", "InfoPlist"]

    static func strings(_ name: String) throws -> [String: [String: Any]] {
        let data = try Data(contentsOf: resources.appendingPathComponent("\(name).xcstrings"))
        let root = try #require(try JSONSerialization.jsonObject(with: data) as? [String: Any])
        return try #require(root["strings"] as? [String: [String: Any]])
    }

    static func keys(_ name: String = "Localizable") throws -> Set<String> {
        Set(try strings(name).keys)
    }

    static func texts() throws -> [CatalogText] {
        try names.flatMap { name in
            try strings(name).flatMap { key, entry -> [CatalogText] in
                let localizations = entry["localizations"] as? [String: Any] ?? [:]
                return localizations.flatMap { language, value in
                    values(in: value).map { CatalogText(catalog: name, key: key, language: language, text: $0) }
                }
            }
        }
    }

    /// Every stringUnit value under a localization: the string, its plural variations and the
    /// variations of its substitutions.
    static func values(in node: Any) -> [String] {
        guard let dict = node as? [String: Any] else { return [] }
        var found: [String] = []
        if let unit = dict["stringUnit"] as? [String: Any], let value = unit["value"] as? String {
            found.append(value)
        }
        for (key, child) in dict where key != "stringUnit" {
            found += values(in: child)
        }
        return found
    }
}

struct CopyRule: Sendable, CustomStringConvertible {
    let name: String
    let pattern: String
    var caseInsensitive = true

    var description: String { name }

    func matches(_ text: String) -> Bool {
        let regex = try! NSRegularExpression(pattern: pattern, options: caseInsensitive ? [.caseInsensitive] : [])
        return regex.firstMatch(in: text, range: NSRange(text.startIndex..., in: text)) != nil
    }

    /// The same names as the web's it.each table, so the two lists can be compared.
    static let prdAndDecisions: [CopyRule] = [
        CopyRule(name: "legality in the client's country", pattern: #"es legal|é legal|is legal|legal en tu país"#),
        CopyRule(
            name: "tax or succession protection",
            pattern: #"impuesto de herencia|imposto de herança|inheritance tax|protección fiscal|proteção fiscal|tax protection|sucesi[oó]n|sucessã?o|sucessóri|succession"#),
        CopyRule(
            name: "returns, or no risk",
            pattern: #"rentabilidad garantizada|rentabilidade garantida|guaranteed return|sin riesgo|sem risco|no risk|risk-free|\bganhe\b|\bganá dinero\b|\bearn returns\b"#),
        CopyRule(name: "money held by OpenDollars", pattern: #"(dinero|dinheiro|money)[^.]*(con|com|with) (a )?OpenDollars"#),
        CopyRule(name: "never mixing money (decision 11)", pattern: #"nunca mezclamos|nunca misturamos|never mix"#),
        CopyRule(name: "fiscal promises (decision 11)", pattern: #"estructura fiscal|estrutura fiscal|tax structure"#),
        CopyRule(name: "opening in minutes (decisions 11, 17)", pattern: #"\ben minutos\b|\bem minutos\b|\bin minutes\b"#),
        CopyRule(name: "crypto or hype language", pattern: #"\bcripto\b|\bcrypto\b|\bwallet\b|\bbilletera\b|\bcarteira digital\b"#),
    ]

    static let partners = CopyRule(name: "partner without a signed contract", pattern: #"Zerohash|Sumsub|Persona\b|Onfido|\beFX\b"#, caseInsensitive: false)
    static let comingSoon = CopyRule(
        name: "debit card or tax reports",
        pattern: #"tarjeta de débito|cartão de débito|debit card|reportes fiscales|relatórios fiscais|tax reports"#)
    static let exclamation = CopyRule(name: "exclamation mark", pattern: #"[!¡]"#)
    static let emoji = CopyRule(name: "emoji", pattern: #"\p{Extended_Pictographic}"#)
    static let tuteo = CopyRule(
        name: "tú instead of vos",
        pattern: #"\b(tú|ti|contigo|tienes|puedes|quieres|debes|eres|necesitas|vienes|prefieres|haz|pon|elige|escribe|sigues|recibirás|podrás|tendrás)\b"#)
}

@Suite struct CopyRulesTests {
    private func offenders(_ rule: CopyRule, in texts: [CatalogText]) -> [String] {
        texts.filter { rule.matches($0.text) }.map(\.description)
    }

    @Test func theCatalogsAreFound() throws {
        let texts = try StringCatalogs.texts()
        // Guards against a vacuous pass: the whole web copy is in the catalog.
        #expect(try StringCatalogs.keys().count > 450)
        #expect(Set(texts.map(\.language)) == ["es", "pt", "en"])
    }

    @Test(arguments: CopyRule.prdAndDecisions)
    func nothingSays(rule: CopyRule) throws {
        #expect(offenders(rule, in: try StringCatalogs.texts()).isEmpty)
    }

    @Test func namesNoPartnerWithoutASignedContract() throws {
        #expect(offenders(.partners, in: try StringCatalogs.texts()).isEmpty)
    }

    @Test func offersTheDebitCardAndTaxReportsOnlyAsComingSoon() throws {
        let elsewhere = try StringCatalogs.texts().filter { !$0.key.hasPrefix("profile.soon.") }
        #expect(offenders(.comingSoon, in: elsewhere).isEmpty)
    }

    @Test func hasNoExclamationMarks() throws {
        #expect(offenders(.exclamation, in: try StringCatalogs.texts()).isEmpty)
    }

    @Test func hasNoEmoji() throws {
        #expect(CopyRule.emoji.matches("Invertí \u{1F680}"), "the emoji pattern must work on this platform")
        #expect(offenders(.emoji, in: try StringCatalogs.texts()).isEmpty)
    }

    @Test func usesVoseoNeverTu() throws {
        let spanish = try StringCatalogs.texts().filter { $0.language == "es" }
        #expect(offenders(.tuteo, in: spanish).isEmpty)
    }

    @Test func putsActionButtonsInTheInfinitive() throws {
        // "Ya envié" is the PRD's own wording for this button (section 6).
        let exceptions: Set<String> = ["deposit.instructions.sent.action"]
        let button = try NSRegularExpression(
            pattern: #"\.actions?\.|\.(action|save|saveChanges|confirm|submit|continue|back|retry|signIn|signOut|stay|start|send|choose|change|create|manage|allow|dismiss)$"#)
        let infinitive = try NSRegularExpression(pattern: #"^[a-záéíóúñ]*(ar|er|ir)(me)?\b"#, options: [.caseInsensitive])
        let buttons = try StringCatalogs.texts().filter { text in
            text.language == "es" && !exceptions.contains(text.key)
                && button.firstMatch(in: text.key, range: NSRange(text.key.startIndex..., in: text.key)) != nil
        }
        #expect(buttons.count > 30)
        let offenders = buttons.filter { infinitive.firstMatch(in: $0.text, range: NSRange($0.text.startIndex..., in: $0.text)) == nil }
        #expect(offenders.isEmpty, "\(offenders)")
    }

    // The converter turned {{date}} into %@ and plurals into variations: every language of a key
    // must still carry the same format specifiers.
    @Test func everyLanguageKeepsTheSamePlaceholders() throws {
        let specifier = try NSRegularExpression(pattern: #"%(\d+\$)?(#@\w+@|@|lld|arg)"#)
        func specifiers(_ text: String) -> Set<String> {
            Set(specifier.matches(in: text, range: NSRange(text.startIndex..., in: text)).compactMap { Range($0.range, in: text).map { String(text[$0]) } })
        }
        let byKey = Dictionary(grouping: try StringCatalogs.texts()) { "\($0.catalog) \($0.key)" }
        var mismatches: [String] = []
        for (key, texts) in byKey {
            let perLanguage = Dictionary(grouping: texts, by: \.language).mapValues { $0.reduce(into: Set<String>()) { $0.formUnion(specifiers($1.text)) } }
            if Set(perLanguage.values).count > 1 { mismatches.append("\(key): \(perLanguage)") }
        }
        #expect(mismatches.isEmpty, "\(mismatches)")
    }
}

// The iOS rule list must keep up with the web's: a rule added there is added here.
// TODO(decisão) 16: the expressions are repeated from the web test; only the names are compared.
@Suite(.enabled(if: WebCopyRulesFile.contents != nil, "web/src/i18n/copy-rules.test.ts not checked out"))
struct CopyRuleParityTests {
    @Test func theRuleNamesMatchTheWebTest() throws {
        let source = try #require(WebCopyRulesFile.contents)
        let entry = try NSRegularExpression(pattern: #"\[\s*"([^"]+)",\s*/"#)
        let webNames = Set(entry.matches(in: source, range: NSRange(source.startIndex..., in: source)).compactMap {
            Range($0.range(at: 1), in: source).map { String(source[$0]) }
        })
        #expect(webNames == Set(CopyRule.prdAndDecisions.map(\.name)))
    }
}

enum WebCopyRulesFile {
    static let contents: String? = try? String(
        contentsOf: StringCatalogs.resources
            .deletingLastPathComponent() // OpenDollars
            .deletingLastPathComponent() // ios
            .deletingLastPathComponent() // repository
            .appendingPathComponent("web/src/i18n/copy-rules.test.ts"),
        encoding: .utf8)
}

// No visible text written in the app's code: every text comes from the catalogs, through the
// generated accessors. Values (amounts, masked numbers) go through Text(verbatim:).
@Suite struct NoLiteralTextTests {
    @Test func theAppHasNoLiteralUserFacingText() throws {
        let literal = try NSRegularExpression(pattern:
            #"\b(?:Text|Button|Label|Link|Toggle|TextField|SecureField|Section|Menu|Picker|NavigationLink)\(\s*"[^"]*\p{L}{2,}"#
            + #"|\.(?:navigationTitle|accessibilityLabel|accessibilityHint|accessibilityValue|alert|confirmationDialog|help)\(\s*"[^"]*\p{L}{2,}"#
            + #"|String\(localized:\s*""#)
        let offences = try AppSources.lines()
            .filter { !$0.file.hasPrefix("Generated/") }
            .filter { literal.firstMatch(in: $0.text, range: NSRange($0.text.startIndex..., in: $0.text)) != nil }
            .map { "\($0.file):\($0.number): \($0.text.trimmingCharacters(in: .whitespaces))" }
        #expect(offences.isEmpty, "\(offences)")
    }
}

// Keys the core builds at run time (by status, step or error code) exist in the catalog: the
// generated accessors cannot check these at compile time.
@Suite struct DynamicKeyTests {
    static let knownStatuses: [AccountStatus] = [.draft, .submitted, .kyc_review, .ibkr_pending, .action_required, .open, .restricted, .rejected, .unknown("frozen")]

    @Test func accountStatusKeys() throws {
        let keys = try StringCatalogs.keys()
        for status in Self.knownStatuses {
            #expect(keys.contains(AccountStatusCopy.titleKey(status)), "\(status)")
            #expect(keys.contains(AccountStatusCopy.bodyKey(status)), "\(status)")
        }
    }

    @Test func timelineKeys() throws {
        let keys = try StringCatalogs.keys()
        for id in AccountTimeline.StepID.allCases { #expect(keys.contains(id.copyKey), "\(id)") }
        for status in [AccountTimeline.StepStatus.done, .current, .upcoming] { #expect(keys.contains(status.copyKey), "\(status)") }
    }

    @Test func errorKeys() throws {
        let keys = try StringCatalogs.keys()
        for code in ClientErrorCode.allCases { #expect(keys.contains(code.copyKey), "\(code)") }
    }
}
